  &.scroll-buttons {
  --scroll-button-size: 36px; --scroll-button-offset: 1rem;
  &::scroll-button(*) { opacity: 0; pointer-events: auto; position: absolute; position-anchor: --carousel--mode-multi-brand-module-carousel; background-color: var(--sema-color-background-default); border-width: medium; border-style: none; border-color: currentcolor; border-image: none; border-radius: 12px; cursor: pointer; display: inline-block; margin-block-start: calc(var(--carousel-item-height) / 2 - var(--scroll-button-size) / 2); height: var(--scroll-button-size); line-height: 0; vertical-align: middle; width: var(--scroll-button-size); transition: opacity 50ms cubic-bezier(0, 0, 1, 1), transform 50ms cubic-bezier(0, 0, 1, 1); }
  &:hover::scroll-button(*) { opacity: 1; transition: opacity 100ms cubic-bezier(0, 0, 1, 1), transform 100ms cubic-bezier(0, 0, 1, 1); }
  &::scroll-button(inline-end) { content: ""; background-image: url("data:image/svg+xml,%3Csvg aria-hidden='true' role='img' viewBox='0 0 24 24' width='16' height='16' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath fill='white' d='M8.7.3 20.42 12 8.71 23.7l-1.42-1.4L17.6 12 7.29 1.7z' /%3E%3C/svg%3E"); background-repeat: no-repeat; background-position: center center; background-size: 16px 16px; background-blend-mode: difference; right: anchor(--carousel--mode-multi-brand-module-carousel right); margin-inline-end: var(--scroll-button-offset); top: anchor(--carousel--mode-multi-brand-module-carousel start); }
  &::scroll-button(inline-start) { content: ""; background-image: url("data:image/svg+xml,%3Csvg aria-hidden='true' role='img' viewBox='0%200%2024%2024' width='16' height='16' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath fill='white' d='m6.41%2012%2010.3-10.3L15.29.3%203.6%2012l11.7%2011.7%201.42-1.4z'/%3E%3C/svg%3E"); background-repeat: no-repeat; background-position: center center; background-size: 16px 16px; background-blend-mode: difference; left: anchor(--carousel--mode-multi-brand-module-carousel left); margin-inline-start: var(--scroll-button-offset); top: anchor(--carousel--mode-multi-brand-module-carousel start); }
  &::scroll-button(*):is(:hover, :focus-visible) { background-color: var(--sema-color-hover-background-default); opacity: 1; }
  &::scroll-button(*):active { background-color: var(--sema-color-pressed-background-default); transform: scale(0.9); }
  &::scroll-button(*):disabled { background-color: var(--sema-color-background-disabled); opacity: 0; cursor: not-allowed; interactivity: inert; }
}
}

